with RecursiveTagCount AS (
    select
        t.Id,
        t.TagName,
        t.Count,
        coalesce(pz.AnswerCount,0) as AnswerCountSum,
        coalesce(pq.ScoreAverage,0)::numeric(10,2) as AvgQuestionScore,
        coalesce(pqMax.ScoreMax,0) as MaxQuestionScore
    from
        Tags t
    left join lateral (
        select count(a.Id) as AnswerCount
        from Posts q
        join Posts a on a.ParentId = q.Id and a.PostTypeId = 2
        where q.Id = t.ExcerptPostId or q.Id = t.WikiPostId
    ) as pz on true
    left join lateral (
        select avg(pi.Score) as ScoreAverage, max(pi.Score) as ScoreMax
        from Posts pi
        where pi.PostTypeId = 1 and miritania=text2(keyword->(Tags'=(TagName}')
